import base64,sys
F="MyPersonas.Online_v0/index.html"
EDITS=[
("A_helpers",
 "YXN5bmMgZnVuY3Rpb24gcmVuZGVyRGlzY292ZXIocSxlcG9jaD0rK3JlbmRlckVwb2NoKXsK",
 ""),
("B_recentfetch",
 "",
 ""),
("C_recenthtml",
 "ICAgICR7cmVjZW50Lmxlbmd0aD9gPGgzIGNsYXNzPSJzZWN0aGVhZCIgc3R5bGU9Im1hcmdpbi10b3A6MjZweCI+UmVjZW50IHBvc3RzPC9oMz4KICAgICR7cmVjZW50Lm1hcChyPT5wb3N0SHRtbChyLHIucGVyc29uYXMsZmFsc2UpKS5qb2luKCIiKX1gOiIifWA7Cg==",
 ""),
("D_rendertag",
 "",
 ""),
("E_pickmine",
 "",
 "")
]
raw=open(F,"rb").read().decode("utf-8")
lf=raw.replace("\r\n","\n")
report=[]
for name,ob,nb in EDITS:
    old=base64.b64decode(ob).decode("utf-8")
    new=base64.b64decode(nb).decode("utf-8")
    if new in lf and old not in lf:
        report.append(name+": ALREADY"); continue
    c=lf.count(old)
    if c!=1:
        print("ABORT",name,"count=",c); sys.exit(2)
    lf=lf.replace(old,new,1)
    report.append(name+": ok")
open(F,"wb").write(lf.replace("\n","\r\n").encode("utf-8"))
print("\n".join(report))
print("DONE len",len(lf))
